/** @param {{des: object}} api */
export default function bigrm_2({ des, selection, percent, math }) {
    des.level_init({ style: 'solidfill', fg: ' ' });
    des.level_flags('mazelevel', 'noflip');

    des.map(`---------------------------------------------------------------------------
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
|.........................................................................|
---------------------------------------------------------------------------
`);
    // Dungeon Description
    des.region(selection.area(1, 1, 73, 16), 'lit');

    let darkness = null;

    const choice = math.random(0, 3);
    if (choice === 0) {
        darkness = selection.bor(
            selection.bor(selection.bor(selection.area(1, 7, 22, 9), selection.area(24, 1, 50, 5)), selection.area(24, 11, 50, 16)),
            selection.area(52, 7, 73, 9)
        );
    } else if (choice === 1) {
        darkness = selection.area(24, 1, 50, 16);
    } else if (choice === 2) {
        darkness = selection.bor(selection.area(1, 1, 22, 16), selection.area(52, 1, 73, 16));
    }

    if (darkness !== null) {
        des.region(darkness, 'unlit');
        if (percent(25)) {
            des.replace_terrain({
                selection: selection.grow(darkness),
                fromterrain: '.', toterrain: 'I',
            });
        }
    }

    // Stairs
    des.stair('up');
    des.stair('down');
    // Non diggable walls
    des.non_diggable();
    // Objects
    for (let i = 1; i <= 15; i++) {
        des.object();
    }
    // Random traps
    for (let i = 1; i <= 6; i++) {
        des.trap();
    }
    // Random monsters.
    for (let i = 1; i <= 28; i++) {
        des.monster();
    }
}
